/**
 * Serve the visual-check page: static files + scene JSONs generated by the
 * real converters. Zero dependencies beyond node:http. Plain JS.
 */
import { createServer } from 'node:http'
import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { convert } from '../../lib/convert/index.js'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..')
const visualDir = path.join(root, 'test', 'visual')

async function loadScenes() {
  const fixtures = path.join(root, 'test', 'fixtures')
  const [step, stl, dxf] = await Promise.all([
    convert(await readFile(path.join(fixtures, 'sample.step')), 'step', 'sample.step'),
    convert(Buffer.from(cubeBinarySTL()), 'stl', 'cube.stl'),
    convert(await readFile(path.join(fixtures, 'sample.dxf')), 'dxf', 'sample.dxf'),
  ])
  return {
    '/scene-3d-step.json': JSON.stringify(step),
    '/scene-3d-stl.json': JSON.stringify(stl),
    '/scene-2d-dxf.json': JSON.stringify(dxf),
  }
}

async function loadStaticScenes() {
  try {
    const model = await readFile(path.join(visualDir, 'scene-3d-model.json'), 'utf8')
    const snowman = await readFile(path.join(visualDir, 'scene-3d-snowman.json'), 'utf8')
    return { '/scene-3d-model.json': model, '/scene-3d-snowman.json': snowman }
  } catch {
    return {}
  }
}

/** Minimal binary STL cube (same construction as the unit test). */
function cubeBinarySTL() {
  const triangleCount = 12
  const buffer = Buffer.alloc(84 + triangleCount * 50)
  buffer.writeUInt32LE(triangleCount, 80)
  let offset = 84
  for (let face = 0; face < 6; face++) {
    const n = [0, 0, 0]
    n[Math.floor(face / 2)] = face % 2 === 0 ? 1 : -1
    const corners =
      face < 2 ? [[0, 0, n[2]], [1, 0, n[2]], [1, 1, n[2]], [0, 1, n[2]]]
      : face < 4 ? [[n[0], 0, 0], [n[0], 1, 0], [n[0], 1, 1], [n[0], 0, 1]]
      : [[0, n[1], 0], [1, n[1], 0], [1, n[1], 1], [0, n[1], 1]]
    for (const tri of [[corners[0], corners[1], corners[2]], [corners[0], corners[2], corners[3]]]) {
      for (const vertex of [n, tri[0], tri[1], tri[2]]) {
        for (const component of vertex) {
          buffer.writeFloatLE(component, offset)
          offset += 4
        }
      }
      offset += 2
    }
  }
  return buffer
}

const scenes = { ...(await loadScenes()), ...(await loadStaticScenes()) }
const server = createServer(async (req, res) => {
  const url = req.url ?? '/'
  if (scenes[url] !== undefined) {
    res.writeHead(200, { 'content-type': 'application/json' })
    res.end(scenes[url])
    return
  }
  try {
    const file = url === '/' ? '/index.html' : url
    const body = await readFile(path.join(visualDir, file))
    res.writeHead(200, { 'content-type': file.endsWith('.js') ? 'text/javascript' : 'text/html' })
    res.end(body)
  } catch {
    res.writeHead(404)
    res.end('not found')
  }
})

await new Promise((resolve) => server.listen(3987, '127.0.0.1', resolve))
// The occt worker keeps the loop alive; that is fine for a dev server.
console.log('visual check: http://127.0.0.1:3987/')
